"""
Base adapter defines the interface the GUI will use.
All adapters must implement: load(), predict(image_path), retrain(trigger_data), and name property.
"""
from abc import ABC, abstractmethod


class BaseAdapter(ABC):
    def __init__(self, cfg):
        self.cfg = cfg

    @abstractmethod
    def load(self):
        """Load model weights or initialize model."""
        pass

    @abstractmethod
    def predict(self, image_path):
        """Return a list of predictions in unified format:
        [{"label": str, "x1": int, "y1": int, "x2": int, "y2": int, "confidence": float}, ...]
        """
        pass

    @abstractmethod
    def retrain(self, annotations):
        """Trigger retraining/fine-tuning given new annotations. May be synchronous or spawn a job."""
        pass

    @property
    @abstractmethod
    def name(self):
        pass

"""
A minimal sklearn adapter for incremental (online) learning.
This is illustrative: the GUI must present features for tabular/text inputs.
"""
import os
import joblib
from models.base_adapter import BaseAdapter
from sklearn.linear_model import SGDClassifier
import numpy as np


class SklearnAdapter(BaseAdapter):
    def __init__(self, cfg, model_path="sk_model.joblib"):
        super().__init__(cfg)
        self.model_path = model_path
        self.model = None

    @property
    def name(self):
        return "sklearn"

    def load(self):
        if os.path.exists(self.model_path):
            self.model = joblib.load(self.model_path)
        else:
            # Example: binary classifier with partial_fit support
            self.model = SGDClassifier(max_iter=5)

    def predict(self, image_path):
        # For tabular/text, image_path is not used. This function is a placeholder.
        return []

    def retrain(self, annotations):
        # annotations: list of (X, y) tuples; here we assume caller supplies feature vectors
        if self.model is None:
            self.load()
        X = np.array([a[0] for a in annotations])
        y = np.array([a[1] for a in annotations])
        # Use partial_fit if available
        if hasattr(self.model, "partial_fit"):
            classes = np.unique(y)
            self.model.partial_fit(X, y, classes=classes)
        else:
            self.model.fit(X, y)
        joblib.dump(self.model, self.model_path)

