import os
import json

MODELS_REGISTRY_FILE = "models.json"


class ModelManager:
    def __init__(self):
        self.registry_path = MODELS_REGISTRY_FILE
        self.models = self.load_registry()

    def load_registry(self):
        """Loads the model registry from models.json."""
        if os.path.exists(self.registry_path):
            with open(self.registry_path, "r") as f:
                return json.load(f)
        else:
            # Return a default registry if the file doesn't exist
            return {"yolov8n.pt": {"name": "YOLOv8-Nano (Default)", "path": "yolov8n.pt"}}

    def save_registry(self):
        """Saves the current model registry to disk."""
        with open(self.registry_path, "w") as f:
            json.dump(self.models, f, indent=4)

    def get_model_names(self):
        """Returns a list of friendly names for all registered models."""
        return [details["name"] for details in self.models.values()]

    def get_model_path(self, friendly_name):
        """Finds the path of a model from its friendly name."""
        for path, details in self.models.items():
            if details["name"] == friendly_name:
                return path
        return None

    def register_model(self, path_to_model, name=None):
        """Adds a new model to the registry."""
        if not os.path.exists(path_to_model):
            print(f"Warning: Model path does not exist: {path_to_model}")
            return

        key = os.path.abspath(path_to_model)
        if key in self.models:
            print(f"Model at path {key} is already registered.")
            return

        if name is None:
            # Generate a default friendly name
            name = f"Custom Model ({os.path.basename(path_to_model)})"

        self.models[key] = {"name": name, "path": key}
        self.save_registry()
        print(f"Registered new model: {name}")
